import {PRESETS,testsFor,newDraft,fileFor,studentErrors} from './classroom.mjs';
import {MECHANISMS} from './core.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'不限时';
const KEY='course-classrooms.v2';
let local;try{local=JSON.parse(localStorage.getItem(KEY))||{};}catch{local={};}
local.profiles??=[];local.drafts??={};
let profile=local.profiles.find(p=>p.key===local.active)||null,data=null,busy=false,modal=null,syncError='',toastTimer;
let teacherForm={title:'第 1 关：两个数的和',description:PRESETS.sum.description,preset:'sum',filePrefix:'JS_L01',dueAt:''};
let reviews={},queueFilter='pending',pendingReview=null,confirmation=0;
const route=()=>location.hash.replace(/^#\/?/,'')||'dashboard';
const go=p=>{location.hash='/'+p;};
const task=()=>data?.assignments.find(a=>a.id===route().split('/')[1]);
const latest=id=>data?.submissions.find(s=>s.assignment_id===id)||null;
function draftFor(id){const k=profile.key+':'+id;return local.drafts[k]??=newDraft(data.assignments.find(a=>a.id===id));}
const draft=()=>task()?draftFor(task().id):null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(local));}catch{toast('本机草稿存储空间不足，请先导出代码。云端提交不受影响。');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,{method='GET',body,token=profile?.token}={}){const r=await fetch(path,{method,headers:{...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let value;try{value=await r.json();}catch{throw new Error('服务暂未就绪，请稍后刷新。');}if(!r.ok)throw new Error(value.error||'操作未完成。');return value;}
function saveProfile(result){const key=result.role+':'+(result.student?.id||result.room.id);profile={key,token:result.token,role:result.role,room:result.room,student:result.student};local.profiles=local.profiles.filter(p=>p.key!==key);local.profiles.push(profile);local.active=key;data=result;persist();}
function syncLabel(){const e=$('#sync-status');if(e)e.textContent=syncError?'同步失败 · 点击刷新':'云端已同步';}
async function refresh(quiet=false){if(!profile)return;const key=profile.key;try{const value=await api('/api/session');if(profile?.key!==key)return;const changed=JSON.stringify({...data,serverTime:''})!==JSON.stringify({...value,serverTime:''});data=value;syncError='';if(!quiet||changed&&!modal&&!busy&&!document.activeElement?.matches('input,textarea,select')&&!/^(lab|submit|teacher\/create|teacher\/review\/)/.test(route()))render();else syncLabel();}catch(e){syncError=e.message;syncLabel();if(!quiet)toast(e.message);}}
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v15',folder:'M3 7V4h6l3 3h9v13H3z',file:'M5 3h9l5 5v13H5z M14 3v6h5 M9 13h6 M9 17h4',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16v-8',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',code:'m8 7-5 5 5 5 M16 7l5 5-5 5 M14 4l-4 16',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',play:'m8 4 13 8-13 8z',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',close:'m6 6 12 12 M6 18 18 6',clipboard:'M9 5H5v16h14V5h-4 M9 3h6v4H9z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const badge=(s,type='neutral')=>`<span class="badge ${type}">${esc(s)}</span>`;
const btn=(s,a,type='primary',attrs='')=>`<button class="btn ${type}" data-action="${a}" ${attrs}>${s}</button>`;
const link=(s,p,type='secondary')=>`<a class="btn ${type}" href="#/${p}">${s}</a>`;
const status=s=>s?badge({pending:'待教师核实',verified:'核实通过',returned:'已退回',draft:'草稿',published:'已发布',closed:'已关闭'}[s]||s,{pending:'warning',verified:'success',returned:'danger',published:'success'}[s]||'neutral'):badge('未提交');
const heading=(k,t,d,a='')=>`<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${esc(t)}</h1><p>${esc(d)}</p></div><div class="heading-actions">${a}</div></div>`;
const empty=(t,d,a='')=>`<div class="empty-state">${icon('folder')}<h3>${esc(t)}</h3><p>${esc(d)}</p><div class="empty-action">${a}</div></div>`;
function header(){const teacher=profile?.role==='teacher';return `<header class="topbar"><a class="brand" href="#/dashboard"><span class="brand-icon">${icon('file')}</span><span>课还没交<span class="brand-en">COURSE / PENDING</span></span></a><nav class="top-links" aria-label="全局导航">${teacher?'<a href="#/teacher/tasks">教学事务</a><a href="#/teacher/reviews">成果核实</a>':'<a href="#/courses">课程中心</a><a href="#/course">教学课堂</a><a href="#/learning">学习中心</a>'}</nav><div class="top-right">${profile?`<button class="sync-control" data-action="refresh" id="sync-status">${syncError?'同步失败 · 点击刷新':'云端已同步'}</button><button class="role-switch" data-action="identity">${teacher?'教师端':'学生端'} · 切换身份</button><span class="avatar">${esc((teacher?profile.room.teacher_name:profile.student.name).slice(0,1))}</span>`:'<span class="semester">公开赛事原型 · 双端协作</span>'}</div></header>`;}
function sidebar(){const teacher=profile.role==='teacher',r=route();const nav=(s,p,i)=>`<a class="nav-item ${r===p?'active':''}" href="#/${p}">${icon(i)}<span>${s}</span></a>`;return `<aside class="sidebar"><div class="workspace-label">${teacher?'教师工作空间':'学生工作空间'} <span>V0.2</span></div>${nav('工作台','dashboard','grid')}<div class="nav-label">教学空间</div>${teacher?nav('教学任务备案','teacher/tasks','book')+nav('新建作业','teacher/create','file')+nav('学生名册','teacher/students','users'):nav('我的课程','courses','book')+nav('教学课堂','course','folder')+nav('学习中心','learning','folder')}<div class="nav-label">成果事务</div>${teacher?nav('成果核实队列','teacher/reviews','clipboard'):nav('实践记录','records','code')+nav('事务记录','transactions','clock')+nav('成绩管理','grades','chart')}<div class="sidebar-bottom"><div class="term-card"><span class="live-dot"></span>课堂码 ${esc(data.room.code)}<small>${esc(data.room.course_name)}<br>${teacher?'发布、核实与退回':'提交后等待教师核实'}</small></div>${btn(icon('users')+'<span>课堂与身份</span>','identity','nav-item')}${btn(icon('help')+'<span>办事指南</span>','help','nav-item')}${btn(icon('settings')+'<span>设计说明 / 演示</span>','design','nav-item')}<div class="prototype-label">REVERSE UX CHALLENGE<br>公开演示 · 课堂数据云端共享</div></div></aside>`;}
function joinForm(code=''){return `<form id="join-room"><label class="field">课堂码<input name="code" required minlength="8" maxlength="8" value="${esc(code)}" placeholder="教师提供的 8 位课堂码"></label><div class="form-grid"><label class="field">学生称呼<input name="name" required maxlength="30" placeholder="例如：林同学"></label><label class="field">学号<input name="studentNumber" required pattern="[A-Za-z0-9]{2,24}" placeholder="例如：20260001"></label></div><button class="btn primary full" type="submit">加入课堂</button></form>`;}
function profileButton(p){return `<button class="profile-row" data-action="activate" data-key="${esc(p.key)}"><span class="avatar">${esc((p.role==='teacher'?p.room.teacher_name:p.student.name).slice(0,1))}</span><span class="grow"><strong>${p.role==='teacher'?'教师 · '+esc(p.room.teacher_name):'学生 · '+esc(p.student.name)}</strong><small>${esc(p.room.course_name)} · ${esc(p.room.code)}</small></span>${icon('chevron')}</button>`;}
function lobby(){return `<main class="lobby"><div class="lobby-intro"><div class="eyebrow">ONE CLASSROOM. TWO SIDES. MANY PROCEDURES.</div><h1>老师发作业，<br>学生交手续。</h1><p>欢迎来到课还没交。选择一个身份，<br>一起走完「发布—提交—核实」的完整流程。</p><div class="lobby-tags">${badge('跨设备共享课堂','success')}${badge('8 处刻意设计的糟糕 UX')}${badge('公开赛事演示')}</div></div><div class="lobby-grid"><section class="panel padded"><div class="lobby-icon">${icon('book')}</div><h2>我是教师</h2><p class="body-copy">创建课堂，发布作业，核实学生提交。</p><form id="create-room"><label class="field">教师称呼<input name="teacherName" required maxlength="30" placeholder="例如：王老师"></label><label class="field">课程名称<input name="courseName" required minlength="2" maxlength="60" value="JavaScript 程序设计"></label><button class="btn primary full" type="submit">创建教学课堂</button></form></section><section class="panel padded"><div class="lobby-icon student">${icon('code')}</div><h2>我是学生</h2><p class="body-copy">使用教师的课堂码加入，完成并提交作业。</p>${joinForm(new URL(location.href).searchParams.get('class')||'')}</section></div>${local.profiles.length?`<section class="panel saved-identities"><h2>继续已有身份</h2><div class="profile-list">${local.profiles.map(profileButton).join('')}</div></section>`:''}<div class="lobby-foot">${btn('使用恢复口令进入已有课堂','recover','secondary')}${btn('查看赛事设计说明','design','secondary')}<p>这是演示身份系统。恢复口令代表对应身份，请自行保留；可使用昵称与演示学号。</p></div></main>`;}
const stat=(s,n,i,note)=>`<div class="stat-card">${icon(i)}<span>${s}</span><strong>${n}</strong><p>${note}</p></div>`;
function teacherDashboard(){const pending=data.submissions.filter(s=>s.status==='pending');return heading('TEACHER / OVERVIEW',data.room.teacher_name+'，欢迎回到课堂。',data.room.course_name+' · 课堂码 '+data.room.code,btn('复制学生邀请链接','invite','secondary'))+`<section class="teacher-hero"><div><span class="hero-kicker">TEACHING AFFAIRS / LIVE CLASSROOM</span><h2>作业发布以后，<br>流程才刚刚开始。</h2><p>检查学生代码与材料，核实评分或退回修改。</p><div>${link('新建作业','teacher/create','lime')}${link('进入核实队列','teacher/reviews','dark-secondary')}</div></div><div class="teacher-room-code"><small>本课堂邀请码</small><strong>${esc(data.room.code)}</strong><span>学生使用该码加入课堂</span></div></section><div class="stats-grid">${stat('课堂学生',data.students.length,'users','跨设备共享本课堂')}${stat('已发布作业',data.assignments.filter(a=>a.status==='published').length,'book','草稿对学生不可见')}${stat('待核实提交',pending.length,'clipboard','核实后才生成成绩')}${stat('核实通过',data.submissions.filter(s=>s.status==='verified').length,'check','保留各版本与反馈')}</div><section class="panel margin-top"><div class="panel-head"><h2>最近提交</h2>${link('全部核实事务','teacher/reviews','secondary small')}</div>${reviewTable(data.submissions.slice(0,5))}</section>`;}
function dashboard(){if(profile.role==='teacher')return teacherDashboard();const submitted=data.assignments.filter(a=>latest(a.id));return heading('STUDENT / OVERVIEW',profile.student.name+'，流程还没走完。','课堂码 '+data.room.code+' · '+data.room.teacher_name+' · 学号 '+profile.student.student_number)+`<section class="hero"><div class="hero-copy"><span class="hero-kicker"><span class="live-dot"></span>本课堂学习提醒</span><h2>代码通过了，<br>还要等老师核实。</h2><p>完成评测、成果归档和教师核实。<br>提交回执与最终成绩分别生成。</p>${link('进入学习中心','learning','lime')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="paper back-paper"></div><div class="paper front-paper"><div class="paper-top">PRACTICE RECORD <span>02</span></div><div class="paper-code">function <b>solve</b>(a, b) {<br>&nbsp; return a + b;<br>}</div><div class="paper-line"></div><div class="stamp">待核实</div></div><span class="floating-label label-one">评测通过 ≠ 核实通过</span></div></section><div class="stats-grid">${stat('已发布任务',data.assignments.length,'book','教师发布后即可看到')}${stat('尚未提交',data.assignments.length-submitted.length,'code','请办理成果归档')}${stat('待教师核实',submitted.filter(a=>latest(a.id).status==='pending').length,'clipboard','提交回执已生成')}${stat('核实通过',submitted.filter(a=>latest(a.id).status==='verified').length,'check','成绩以教师核实为准')}</div><section class="panel margin-top"><div class="panel-head"><h2>本课堂作业</h2>${link('查看实践记录','records','secondary small')}</div>${assignmentTable()}</section>`;}
function assignmentTable(){if(!data.assignments.length)return empty('教师尚未发布作业','草稿不会显示在学生端。教师发布后，刷新即可查看。',btn('刷新课堂','refresh','secondary'));return `<div class="table-wrap"><table><thead><tr><th>任务名称</th><th>开放状态</th><th>截止时间</th><th>我的提交</th><th>操作</th></tr></thead><tbody>${data.assignments.map(a=>{const s=latest(a.id);return `<tr><td><strong>${esc(a.title)}</strong><small>${PRESETS[a.preset].label}</small></td><td>${status(a.status)}</td><td>${date(a.due_at)}</td><td>${status(s?.status)}</td><td>${link(s&&s.status!=='returned'?'查看提交':'进入实训','lab/'+a.id,'primary small')}</td></tr>`;}).join('')}</tbody></table></div>`;}
function records(){return heading('LEARNING / PRACTICE','实践记录',data.room.course_name+' · 代码评测、正式提交、教师核实分别管理。')+`<section class="panel"><div class="panel-head"><h2>课堂实训任务</h2>${badge(data.assignments.length+' 项')}</div>${assignmentTable()}</section>`;}
function courses(){return heading('TEACHING / COURSES','我的课程','当前身份已加入的课堂。')+`<article class="course-card single-course"><div class="course-cover mint"><span>JS</span><span class="course-cover-caption">PRACTICE<br>MAKES PROGRESS.</span>${icon('code')}</div><div class="course-body">${badge('课堂码 '+data.room.code)}<h2>${esc(data.room.course_name)}</h2><p>${esc(data.room.teacher_name)} · ${data.assignments.length} 项作业</p><div class="course-card-bottom"><span>学生 ${esc(profile.student.student_number)}</span>${link('查看课堂','course','primary small')}</div></div></article>`;}
function course(){return heading('CLASSROOM / OVERVIEW',data.room.course_name,'教师 '+data.room.teacher_name+' · 课堂码 '+data.room.code)+`<div class="tabs"><span class="tab active">课堂概览</span><a class="tab" href="#/learning">课程事务</a><a class="tab" href="#/grades">学习成果</a></div><section class="panel padded"><h2>实践任务按课程事务分别办理。</h2><p class="body-copy">任务书、接口、示例与归档要求由不同模块维护。完成评测并提交后，请等待教师核实，再查询最终成绩。</p><div class="margin-top">${link('办理课程事务','learning','primary')}</div></section>`;}
function learning(){return heading('LEARNING / CENTER','学习中心','课程学习、事务办理与成果认定分别管理。')+`<div class="directory-grid">${[['课程事务','查看课程事项与实践记录。','affairs','folder'],['课程学习','浏览课程概览和课堂信息。','courses','book'],['学习成果','查询教师已核实的最终成绩。','grades','chart']].map(c=>`<a class="directory-card" href="#/${c[2]}">${icon(c[3])}<span class="section-eyebrow">CLASSROOM SERVICES</span><h2>${c[0]}</h2><p>${c[1]}</p><span class="text-link">查看事项</span></a>`).join('')}</div>`;}
function affairs(){return heading('LEARNING / AFFAIRS','课程事务','请按事项类型办理。')+`<section class="panel"><a class="affair-row" href="#/records"><span class="course-icon mint">${icon('code')}</span><div class="grow"><h3>实践记录</h3><p>查找任务、进入实训、评测代码与成果归档。</p></div>${icon('chevron')}</a><a class="affair-row" href="#/grades"><span class="course-icon mint">${icon('chart')}</span><div class="grow"><h3>成果认定</h3><p>查询待核实、退回及已认定成绩。</p></div>${icon('chevron')}</a></section>`;}
const taskHeading=(a,t,k='PRACTICE / TASK')=>heading(k,t,data.room.course_name+' · '+a.title,link('返回实践记录','records','secondary small'));
const missingTask=()=>empty('当前作业不可用','请刷新课堂或返回实践记录选择作业。',link('返回实践记录','records'));
function materials(){const a=task();if(!a)return missingTask();return taskHeading(a,'教学资料','TEACHING / MATERIALS')+`<section class="panel padded"><div class="section-eyebrow">资料 01 / 编程接口</div><h2>${PRESETS[a.preset].label}</h2><p class="body-copy">${esc(PRESETS[a.preset].description)}无需读取标准输入，也无需打印答案。</p><pre class="light-code">function solve(a, b) {\n  // 根据任务要求返回结果\n}</pre><p class="body-copy">示例请前往课堂公告。</p>${link('课堂公告','notices/'+a.id,'secondary small')}</section><section class="panel padded margin-top"><details><summary>其他资料与说明</summary><div class="details-body"><details><summary>归档补充说明（学生版）</summary><div class="rules"><ol><li>当前代码通过全部 8 个用例。</li><li>归档文件名：<code>${esc(fileFor(a,profile.student))}</code>。</li><li>课程全称：<code>${esc(data.room.course_name)}</code>。</li><li>作业全称：<code>${esc(a.title)}</code>。</li><li>填写当前评测编号，附件内容与评测代码相同，不超过 32 KB。</li><li>说明不少于 12 字符，完成三轮确认，等待教师核实。</li></ol></div></details></div></details></section><div class="margin-top">${link('返回实训','lab/'+a.id)}</div>`;}
function notices(){const a=task();if(!a)return missingTask();return taskHeading(a,'课堂公告','TEACHING / NOTICES')+`<section class="panel padded"><div class="notice-meta">${esc(data.room.teacher_name)} · ${date(a.published_at||a.created_at)}</div><h2>${esc(a.title)}：任务要求</h2><p class="body-copy pre-line">${esc(a.description)}</p><div class="example-grid">${testsFor(a.preset).slice(0,2).map(t=>`<div><small>输入</small><code>a = ${t.args[0]}, b = ${t.args[1]}</code><small>返回值</small><code>${t.expected}</code></div>`).join('')}</div><p class="body-copy">评测通过不代表最终成绩。正式提交后，由教师核实评分。</p></section><div class="margin-top">${link('返回实训','lab/'+a.id)}</div>`;}
const locked=a=>{const s=latest(a.id);return s&&s.status!=='returned';};
function submissionBanner(s,a){return `<div class="submission-banner ${s.status}"><div>${status(s.status)}<strong>第 ${s.version} 次提交</strong><p>${s.status==='returned'?esc(s.feedback):s.status==='verified'?'教师已核实，成绩 '+s.score+' 分。':'提交已保存到云端，等待教师核实。'}</p></div>${link('查看回执','submit/'+a.id,'secondary small')}</div>`;}
function evaluationView(e){if(!e)return '<div class="terminal-empty">'+icon('play')+'<p>尚未发起评测</p><span>请先填写运行资源申请。</span></div>';return `<div class="eval-summary"><div>${badge(e.passed?'评测通过':'评测未通过',e.passed?'success':'danger')}<span>${e.results.filter(t=>t.passed).length} / 8</span></div></div>${e.error?`<p class="runtime-error">${esc(e.error)}</p>`:''}<div class="test-chips">${e.results.map((r,i)=>`<span class="${r.passed?'pass':'fail'}">${r.passed?'✓':'×'} ${i+1}</span>`).join('')}</div><div class="result-id">结果编号 <code>${esc(e.id)}</code>${btn('复制','copy-evaluation','secondary small')}</div><details class="test-details"><summary>评测明细</summary><div class="table-wrap"><table><thead><tr><th>输入</th><th>预期</th><th>实际</th></tr></thead><tbody>${e.results.map(r=>`<tr><td>${r.args.join(', ')}</td><td>${r.expected}</td><td>${esc(r.actual)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function lab(){const a=task();if(!a)return missingTask();const d=draft(),s=latest(a.id),passed=d.evaluation?.passed&&d.evaluation.code===d.code;return taskHeading(a,a.title)+(s?submissionBanner(s,a):'')+`<div class="lab-grid"><section class="panel task-panel"><div class="panel-head"><h2>任务书</h2>${status(a.status)}</div><div class="task-body"><div class="section-eyebrow">${esc(a.file_prefix)}</div><h2>${PRESETS[a.preset].label}</h2><p>实现本关函数，通过评测后办理成果归档。</p><div class="task-callout">教师要求、接口与示例由不同模块维护，请分别查阅。</div><a class="resource-row" href="#/materials/${a.id}">${icon('file')}接口与归档资料 ${icon('chevron')}</a><a class="resource-row" href="#/notices/${a.id}">${icon('book')}任务要求与示例公告 ${icon('chevron')}</a><div class="task-foot"><span class="subtle">提交截止</span><strong>${date(a.due_at)}</strong></div></div></section><div class="coding-column"><section class="editor-panel"><div class="editor-top"><span>${icon('code')} main.js</span><span>JavaScript · 浏览器 Worker</span></div><div class="code-area"><div class="line-numbers" id="line-numbers">${d.code.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="code-editor" aria-label="JavaScript 代码编辑器" spellcheck="false" ${locked(a)?'readonly':''}>${esc(d.code)}</textarea></div><div class="editor-bottom"><span id="draft-status">${locked(a)?'已提交锁定；教师退回后可修改':'草稿保存在当前浏览器'}</span><div>${btn('保存草稿','save','dark-secondary')}${btn(icon('play')+' 申请运行','run','lime',locked(a)?'disabled':'')}</div></div></section><section class="panel results-panel"><div class="panel-head"><h2>评测结果 <span id="current-pass">${passed?badge('当前版本通过','success'):''}</span></h2>${btn('导出代码','export-code','secondary small')}</div><div class="result-body">${evaluationView(d.evaluation)}${!locked(a)?`<div class="eval-next"><span>评测完成后仍需单独归档。</span>${link('办理成果归档','submit/'+a.id,'primary small')}</div>`:''}</div></section></div></div>`;}
const draftInput=(s,k,d)=>`<label class="field">${s}<input data-draft="${k}" value="${esc(d[k])}" maxlength="150" placeholder="请填写${s}"></label>`;
function submit(){const a=task();if(!a)return missingTask();const d=draft(),s=latest(a.id);if(s&&s.status!=='returned')return receipt(a,s);return taskHeading(a,'学习成果归档','OUTCOMES / SUBMIT')+(s?submissionBanner(s,a):'')+`<div class="submission-grid"><section class="panel padded"><div class="form-section-title"><span>01</span><h2>成果基本信息</h2></div><div class="form-grid">${draftInput('课程全称','course',d)}${draftInput('作业全称','task',d)}</div>${draftInput('评测结果编号','evaluationId',d)}<div class="form-section-title separated"><span>02</span><h2>成果附件</h2></div><div class="upload-box">${icon('file')}<strong>${d.attachment?esc(d.attachment.name):'添加代码成果'}</strong><p>提取编辑区代码，或上传本地文件。</p><div>${btn('提取当前代码','extract','secondary small')}<label class="btn secondary small file-button">选择本地文件<input type="file" id="attachment-input" accept=".js,.txt"></label></div></div>${draftInput('归档文件名','filename',d)}<label class="field">归档说明<textarea data-draft="note" maxlength="2000" rows="3">${esc(d.note)}</textarea></label><div class="form-actions">${link('返回实训','lab/'+a.id)}${btn('申请归档','archive')}</div></section><aside class="panel padded"><div class="section-eyebrow">ARCHIVE STATUS</div><h2>成果办理进度</h2><ol class="vertical-steps"><li class="${d.evaluation?.passed?'done':'current'}"><strong>代码评测</strong><p>通过全部用例</p></li><li class="current"><strong>材料核验与三轮确认</strong><p>填写并提交到云端</p></li><li><strong>教师核实</strong><p>通过评分或退回修改</p></li><li><strong>成绩认定</strong><p>通过后生成最终成绩</p></li></ol><p class="small-print">状态异常时，请到事务记录展开处理详情。</p></aside></div>`;}
function receipt(a,s){return taskHeading(a,'学习成果提交回执','OUTCOMES / RECEIPT')+`<section class="panel receipt"><div class="receipt-check">${icon(s.status==='verified'?'check':'clock')}</div><div class="section-eyebrow">${s.status==='verified'?'VERIFIED BY TEACHER':'SUBMITTED TO CLASSROOM'}</div><h1>${s.status==='verified'?'老师核实过，才算交稳了。':'这次，提交到老师那里了。'}</h1><p>${s.status==='verified'?'教师已完成核实并评分。':'提交已保存到课堂，最终成绩等待教师核实。'}</p><div class="receipt-meta"><div><small>回执 / 版本</small><strong>${esc(s.id)}<br>第 ${s.version} 次</strong></div><div><small>核实状态 / 最终成绩</small><strong>${status(s.status)}<br>${s.score===null?'待核实':s.score+' / 100'}</strong></div><div><small>作业 / 学生</small><strong>${esc(a.title)}<br>${esc(profile.student.name)} · ${esc(profile.student.student_number)}</strong></div><div><small>提交时间 / 核实时间</small><strong>${date(s.submitted_at)}<br>${s.reviewed_at?date(s.reviewed_at):'尚未核实'}</strong></div></div>${s.feedback?`<p class="teacher-feedback">教师反馈：${esc(s.feedback)}</p>`:''}<div class="receipt-actions">${btn('下载提交回执','download-receipt')}${link('查询成绩','grades')}</div></section>`;}
function grades(){return heading('OUTCOMES / GRADES','成绩管理','浏览器评测仅作参考，最终成绩由教师核实后生成。')+`<section class="panel"><div class="panel-head"><h2>我的作业成绩</h2>${btn('刷新核实状态','refresh','secondary small')}</div>${data.assignments.length?`<div class="table-wrap"><table><thead><tr><th>作业</th><th>版本</th><th>核实状态</th><th>成绩</th><th>教师反馈</th><th>操作</th></tr></thead><tbody>${data.assignments.map(a=>{const s=latest(a.id);return `<tr><td><strong>${esc(a.title)}</strong></td><td>${s?'第 '+s.version+' 次':'—'}</td><td>${status(s?.status)}</td><td>${s?.status==='verified'?s.score:'—'}</td><td class="feedback-cell">${esc(s?.feedback||'—')}</td><td>${link(s?'查看提交':'进入实训',(s?'submit/':'lab/')+a.id,'secondary small')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('暂无作业','等待教师发布。')}</section>`;}
function transactions(){const logs=[];for(const a of data.assignments)for(const l of draftFor(a.id).logs)logs.push({...l,assignment:a.title});logs.sort((a,b)=>b.time.localeCompare(a.time));return heading('AFFAIRS / TRANSACTIONS','事务记录','状态码背后的原因，请展开处理详情。')+`<section class="panel"><div class="panel-head"><h2>本机处理记录</h2>${badge(logs.length+' 条')}</div>${logs.length?logs.map(l=>`<details class="transaction"><summary><span class="transaction-icon ${l.error?'error':''}">${icon('file')}</span><span class="grow"><strong>${esc(l.title)}</strong><small>${esc(l.assignment)} · ${date(l.time)}</small></span><span class="text-link">处理详情</span></summary><div class="transaction-details">${l.details.map(t=>'<p>'+esc(t)+'</p>').join('')}</div></details>`).join(''):empty('暂无事务记录','运行或材料受阻时，会保留可恢复的处理详情。')}</section>`;}
function teacherTasks(){return heading('TEACHING / TASKS','教学任务备案','先保存草稿，再单独发布。草稿对学生不可见。',link('新建作业','teacher/create','primary'))+`<section class="panel"><div class="panel-head"><h2>作业清单</h2>${badge(data.assignments.length+' 项')}</div>${data.assignments.length?`<div class="table-wrap"><table><thead><tr><th>作业</th><th>评测模板</th><th>状态</th><th>截止时间</th><th>提交次数</th><th>操作</th></tr></thead><tbody>${data.assignments.map(a=>`<tr><td><strong>${esc(a.title)}</strong><small>归档前缀 ${esc(a.file_prefix)}</small></td><td>${PRESETS[a.preset].label}</td><td>${status(a.status)}</td><td>${date(a.due_at)}</td><td>${data.submissions.filter(s=>s.assignment_id===a.id).length}</td><td>${btn(a.status==='draft'?'发布给学生':a.status==='published'?'结束收取':'重新开放',a.status==='draft'?'publish-task':a.status==='published'?'close-task':'reopen-task',a.status==='draft'?'primary small':'secondary small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有作业','新建一份草稿，再办理发布。',link('新建作业','teacher/create','primary'))}</section>`;}
function teacherCreate(){return heading('TEACHING / REGISTRATION','新建作业','支持三种真实可运行的 JavaScript 评测模板。保存草稿不等于发布。')+`<div class="submission-grid"><section class="panel padded"><form id="create-assignment"><label class="field">作业标题<input name="title" data-teacher="title" required minlength="2" maxlength="80" value="${esc(teacherForm.title)}"></label><label class="field">评测模板<select name="preset" data-teacher="preset" aria-label="评测模板">${Object.entries(PRESETS).map(([k,p])=>`<option value="${k}" ${k===teacherForm.preset?'selected':''}>${p.label}</option>`).join('')}</select></label><label class="field">任务说明<textarea name="description" data-teacher="description" rows="5" required minlength="8" maxlength="4000">${esc(teacherForm.description)}</textarea></label><div class="form-grid"><label class="field">归档文件名前缀<input name="filePrefix" data-teacher="filePrefix" required pattern="[A-Za-z][A-Za-z0-9_]{1,23}" value="${esc(teacherForm.filePrefix)}"><small>学生文件名：前缀_学号.js</small></label><label class="field">截止时间（可选）<input name="dueAt" data-teacher="dueAt" type="datetime-local" value="${esc(teacherForm.dueAt)}"></label></div><div class="form-actions">${link('返回任务备案','teacher/tasks')}<button class="btn primary" type="submit">保存作业草稿</button></div></form></section><aside class="panel padded"><div class="section-eyebrow">PUBLICATION PROCESS</div><h2>保存 ≠ 发布</h2><p class="body-copy">草稿只有教师可见。请到「教学任务备案」单独发布，学生刷新后即可看到。</p><p class="body-copy">评测模板决定函数目标与测试用例，请保持任务说明一致。已发布题目不再修改，以保留提交依据。</p></aside></div>`;}
function teacherStudents(){return heading('TEACHING / MEMBERS','课堂学生名册','学生用课堂码加入后显示在此处。',btn('复制学生邀请链接','invite','primary'))+`<section class="panel"><div class="panel-head"><h2>课堂码 ${esc(data.room.code)}</h2>${badge(data.students.length+' 位学生')}</div>${data.students.length?`<div class="table-wrap"><table><thead><tr><th>学生</th><th>学号</th><th>加入时间</th><th>提交次数</th></tr></thead><tbody>${data.students.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.student_number)}</td><td>${date(s.created_at)}</td><td>${data.submissions.filter(t=>t.student_id===s.id).length}</td></tr>`).join('')}</tbody></table></div>`:empty('学生还没有加入','把课堂码或邀请链接提供给学生。')}</section>`;}
function reviewTable(list){if(!list.length)return empty('暂无对应提交','学生正式提交后会进入核实队列。');return `<div class="table-wrap"><table><thead><tr><th>学生 / 学号</th><th>作业 / 版本</th><th>提交时间</th><th>状态</th><th>成绩</th><th>操作</th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${esc(s.student_name)}</strong><small>${esc(s.student_number)}</small></td><td><strong>${esc(s.assignment_title)}</strong><small>第 ${s.version} 次</small></td><td>${date(s.submitted_at)}</td><td>${status(s.status)}</td><td>${s.score??'—'}</td><td>${link(s.status==='pending'?'核实成果':'查看记录','teacher/review/'+s.id,'primary small')}</td></tr>`).join('')}</tbody></table></div>`;}
function teacherReviews(){return heading('OUTCOMES / VERIFICATION','成果核实队列','检查代码、评测记录与材料，通过评分或退回修改。',btn('刷新提交列表','refresh','secondary'))+`<div class="queue-tabs">${[['pending','待核实'],['verified','已通过'],['returned','已退回'],['all','全部版本']].map(([k,t])=>btn(t+' '+data.submissions.filter(s=>k==='all'||s.status===k).length,'queue-filter',queueFilter===k?'primary small':'secondary small',`data-filter="${k}"`)).join('')}</div><section class="panel">${reviewTable(data.submissions.filter(s=>queueFilter==='all'||s.status===queueFilter))}</section>`;}
function teacherReview(){const s=data.submissions.find(s=>s.id===route().split('/')[2]);if(!s)return empty('没有找到提交','返回核实队列刷新。',link('返回核实队列','teacher/reviews'));const a=data.assignments.find(a=>a.id===s.assignment_id),f=reviews[s.id]??={score:100,feedback:'',checkedCode:false,checkedMaterial:false};return heading('VERIFICATION / REVIEW',s.student_name+'的学习成果',a.title+' · 第 '+s.version+' 次提交',link('返回核实队列','teacher/reviews'))+`<div class="review-layout"><section class="panel padded"><div class="panel-head flush"><h2>学生提交代码</h2>${status(s.status)}</div><div class="review-meta"><span>学号 ${esc(s.student_number)}</span><span>${esc(s.filename)}</span><span>${date(s.submitted_at)}</span></div><pre class="review-code">${esc(s.code)}</pre><h3>学生归档说明</h3><p class="body-copy pre-line">${esc(s.note)}</p><details class="test-details"><summary>任务要求与浏览器评测记录</summary><p class="body-copy pre-line">${esc(a.description)}</p><div class="table-wrap"><table><thead><tr><th>输入</th><th>预期</th><th>浏览器返回</th></tr></thead><tbody>${s.evaluation.results.map(r=>`<tr><td>${r.args.join(', ')}</td><td>${r.expected}</td><td>${esc(r.actual)}</td></tr>`).join('')}</tbody></table></div><p class="small-print">浏览器评测仅为学生侧辅助记录，最终成绩由教师核实代码和材料后认定。</p></details></section><aside class="panel padded"><div class="section-eyebrow">TEACHER VERIFICATION</div><h2>核实处理</h2><p class="small-print">回执 ${esc(s.id)}</p>${s.status==='pending'?`<label class="check-row"><input type="checkbox" data-review="checkedCode" ${f.checkedCode?'checked':''}>已检查学生代码与任务要求。</label><label class="check-row"><input type="checkbox" data-review="checkedMaterial" ${f.checkedMaterial?'checked':''}>已核对附件名称与归档说明。</label><label class="field">核实成绩（0–100）<input type="number" min="0" max="100" step="1" data-review="score" value="${esc(f.score)}"></label><label class="field">教师反馈<textarea data-review="feedback" rows="4" maxlength="2000" placeholder="退回时至少填写 4 字符的原因">${esc(f.feedback)}</textarea></label><div class="review-actions">${btn('核实通过并评分','review-approve')}${btn('退回学生修改','review-return','secondary')}</div>`:`<div class="review-result">${status(s.status)}<strong>${s.score===null?'等待学生重新提交':s.score+' 分'}</strong><p>${esc(s.feedback||'无额外反馈。')}</p><small>${date(s.reviewed_at)}</small></div>`}</aside></div>`;}
const studentPages={dashboard,courses,course,learning,affairs,records,materials,notices,lab,submit,grades,transactions};
const teacherPages={dashboard:teacherDashboard,'teacher/tasks':teacherTasks,'teacher/create':teacherCreate,'teacher/students':teacherStudents,'teacher/reviews':teacherReviews};
function render(){if(!profile||!data){$('#app').innerHTML=header()+lobby();return;}const r=route(),teacher=profile.role==='teacher';const body=teacher?(r.startsWith('teacher/review/')?teacherReview():(teacherPages[r]||teacherDashboard)()):(studentPages[r.split('/')[0]]||dashboard)();document.title=(teacher?'教师端':'学生端')+' · 课还没交';$('#app').innerHTML=header()+sidebar()+`<main class="main"><div class="breadcrumbs"><span>${teacher?'教师':'学生'}工作空间</span>${icon('chevron')}<span>${esc(data.room.course_name)}</span></div>${body}<footer class="footer"><span>课还没交 · 双端教学事务平台</span><span>独立赛事原型 · 非头歌官方产品</span></footer></main>`;}
const modalHead=(t,k='事务办理')=>`<div class="modal-header"><div><div class="section-eyebrow">${k}</div><h2>${esc(t)}</h2></div>${busy?'':btn(icon('close'),'close-modal','icon-button','aria-label="关闭弹窗"')}</div>`;
function openModal(type,content,wide=false){modal={type};$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'design-modal':''}" role="dialog" aria-modal="true" aria-label="${type}">${content}</section></div>`;$('#modal-root input,#modal-root select,#modal-root button')?.focus();}
function closeModal(){if(busy)return;modal=null;$('#modal-root').innerHTML='';}
function failStudent(errors){const d=draft();if(d){d.stats.errors++;d.logs.unshift({title:'操作未完成 · E-042',error:true,time:new Date().toISOString(),details:errors});persist();}openModal('error',modalHead('操作未完成')+`<div class="error-symbol">!</div><div class="error-copy"><strong>Submission Failed</strong><code>状态码：E-042</code><p>请到事务记录展开处理详情。</p></div><div class="modal-actions">${btn('关闭','close-modal','secondary')}${btn('查阅事务记录','open-transactions')}</div>`);}
function identity(){openModal('identity',modalHead('课堂与身份','CLASSROOM / IDENTITY')+`<p class="modal-description">切换本设备保存的身份。学生身份不能发布或核实作业。</p><div class="profile-list">${local.profiles.map(profileButton).join('')}</div>${profile?`<div class="identity-current"><h3>${esc(profile.room.course_name)}</h3><p>课堂码 <strong>${esc(profile.room.code)}</strong></p>${profile.role==='teacher'?btn('复制学生邀请链接','invite','secondary small'):''}${btn('复制当前身份恢复口令','copy-token','secondary small')}</div>`:''}<div class="modal-actions">${btn('使用恢复口令','recover','secondary')}${profile?.role==='teacher'?btn('以新学生身份体验','join-current','secondary'):''}${btn('创建或加入其他课堂','lobby')}</div>`);}
function recover(){openModal('recover',modalHead('恢复已有身份','RESTORE IDENTITY')+`<p class="modal-description">口令对应的角色与课堂由服务端识别。</p><form id="recover-session"><label class="field">身份恢复口令<input name="token" type="password" required pattern="[a-f0-9]{64}" autocomplete="off" placeholder="64 位恢复口令"></label><div class="modal-actions"><button class="btn primary" type="submit">恢复课堂身份</button></div></form>`);}
function showDesign(){openModal('design',modalHead('难用，但师生真的连通。','REVERSE UX / DUAL ROLE')+`<p class="modal-description">教师创建课堂 → 发布作业 → 学生提交 → 教师核实通过或退回 → 学生查询最终成绩。课堂数据保存到云端，角色权限由服务端核验。</p><div class="design-mechanisms">${MECHANISMS.map((m,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${m[0]}</h3><p>${m[1]}</p><small>刻意反转：${m[2]}</small></div></article>`).join('')}</div><details class="demo-guide"><summary>完整演示路线与示例代码</summary><ol class="help-list"><li>教师创建课堂，新建作业草稿，到任务备案单独发布。</li><li>分享课堂码或邀请链接，让学生加入；也可切换身份体验。</li><li>学生从学习中心 → 课程事务 → 实践记录进入任务。</li><li>查资料、写代码、申请运行，等待 6 秒后复制评测编号。</li><li>按归档说明填材料并完成三轮确认，生成待核实回执。</li><li>教师核实代码和材料，评分通过或填写原因退回。</li><li>学生查成绩；退回后修改并重新提交，保留全部版本。</li></ol>${task()?`<pre class="light-code">${esc(PRESETS[task().preset].solution)}</pre>${btn('复制本关示例代码','copy-solution','secondary small')}`:''}</details><p class="small-print">首版为课堂码与恢复口令保护的赛事演示，不接入学校实名账号。课堂码用于邀请学生；教师恢复口令用于教师身份恢复，请自行保留。浏览器评测仅作核实参考，教师通过后才给分。海报仍需通过 Dify 的 AMD 插件生成。</p><div class="modal-actions">${btn('返回体验','close-modal')}</div>`,true);}
function showRun(){if(locked(task()))return;openModal('run',modalHead('运行资源使用申请','EXECUTION REQUEST')+`<p class="modal-description">请先登记运行用途、预计次数与理由。</p><form id="run-form"><label class="field">运行用途<select name="purpose" aria-label="运行用途" required><option value="">请选择</option><option>验证本次代码实现</option><option>检查修改后的代码</option><option>确认代码仍然正确</option></select></label><label class="field">预计运行次数<input name="count" type="number" min="1" max="99" value="1" required></label><label class="field">运行理由<textarea name="reason" required minlength="8" maxlength="300" rows="3" placeholder="至少 8 个字符"></textarea></label><div class="modal-actions"><button class="btn primary" type="submit">提交运行申请</button></div></form>`);}
function showConfirmation(){const steps=[['材料真实性确认','请核对课程、作业、编号和附件。','<label class="check-row"><input id="confirm-check" type="checkbox">我已核对全部归档材料。</label>'],['归档意愿再次确认','前次确认仅代表材料核对，请再次表达提交意愿。','<label class="field">请输入「确认归档」<input id="confirm-text" placeholder="确认归档"></label>'],['最终提交确认','本次确认后才会保存到课堂，并进入教师核实队列。','<label class="check-row"><input id="confirm-check" type="checkbox">我理解：提交成功后还需等待教师核实。</label>']];const [t,d,f]=steps[confirmation];openModal('confirmation',modalHead(t,`CONFIRMATION ${confirmation+1} / 3`)+`<div class="confirmation-dots">${[0,1,2].map(i=>`<span class="${i<=confirmation?'on':''}"></span>`).join('')}</div><p class="modal-description">${d}</p><div class="confirmation-summary"><strong>${esc(task().title)}</strong><code>${esc(draft().filename)}</code></div>${f}<div class="modal-actions">${btn('暂不提交','close-modal','secondary')}${btn(confirmation===2?'最终提交到课堂':'确认并继续','confirm-next')}</div>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板。');}catch{openModal('copy',modalHead('请手动复制')+`<textarea class="copy-field" readonly>${esc(text)}</textarea>`);$('.copy-field').select();}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function runCode(code,tests){return new Promise(resolve=>{let worker;try{worker=new Worker(new URL('./runner.worker.js',import.meta.url));}catch(e){resolve({results:[],error:e.message});return;}const requestId=crypto.randomUUID();let done=false;const finish=v=>{if(done)return;done=true;clearTimeout(timer);worker.terminate();resolve(v);};const timer=setTimeout(()=>finish({results:[],error:'执行超过 2 秒，已终止。请检查无限循环。'}),2000);worker.onmessage=e=>{if(e.data.requestId===requestId)finish(e.data);};worker.onerror=e=>{e.preventDefault();finish({results:[],error:e.message});};worker.postMessage({requestId,code,tests});});}
async function startRun(form){const a=task(),d=draft(),v=new FormData(form),code=d.code;d.stats.applications++;d.logs.unshift({title:'运行申请已登记',time:new Date().toISOString(),details:['用途：'+v.get('purpose'),'理由：'+v.get('reason')]});persist();closeModal();busy=true;openModal('waiting',modalHead('正在处理运行申请','RESOURCE COORDINATION')+`<div class="waiting-display"><span id="waiting-number">12</span><small>%</small></div><div class="waiting-track"><span id="waiting-bar" style="width:12%"></span></div><h3 class="center" id="waiting-label">正在分配运行资源…</h3><p class="modal-description center">请保持页面，等待学习成果同步。</p>`);const result=await runCode(code,testsFor(a.preset));$('#waiting-number').textContent='99';$('#waiting-bar').style.width='99%';$('#waiting-label').textContent='正在同步学习成果…';setTimeout(()=>{d.stats.waitSeconds+=6;const e={id:'EVAL-'+crypto.randomUUID().slice(0,8).toUpperCase(),code,results:result.results,error:result.error,passed:result.results.length===8&&result.results.every(t=>t.passed)&&!result.error,time:new Date().toISOString()};d.evaluation=e;d.history.unshift(e);d.logs.unshift({title:e.passed?'代码评测已通过':'代码评测未通过',time:e.time,details:['结果编号：'+e.id,`通过 ${e.results.filter(t=>t.passed).length} / 8 个用例。`,...(e.error?[e.error]:[])]});persist();busy=false;closeModal();render();toast(e.passed?'代码通过，请另行归档并等待教师核实。':'评测未通过，请查看明细。');},6000);}
async function mutate(path,body={}){if(busy)return;busy=true;try{const result=await api(path,{method:'POST',body});data=result;syncError='';busy=false;closeModal();render();return result;}catch(e){busy=false;throw e;}}
async function activate(key){const p=local.profiles.find(p=>p.key===key);if(!p)return;closeModal();profile=p;local.active=key;data=null;persist();await refresh();if(data){go('dashboard');render();}}
function prepareReview(decision){const s=data.submissions.find(s=>s.id===route().split('/')[2]),f=reviews[s.id];if(decision==='verified'&&(!f.checkedCode||!f.checkedMaterial)){toast('请完成代码与材料两项核实。');return;}if(decision==='returned'&&f.feedback.trim().length<4){toast('退回时至少填写 4 个字符的原因。');return;}if(decision==='verified'&&(!Number.isInteger(Number(f.score))||Number(f.score)<0||Number(f.score)>100)){toast('成绩必须为 0–100 的整数。');return;}pendingReview={...f,decision,score:Number(f.score)};openModal('review',modalHead(decision==='verified'?'确认核实通过':'确认退回修改')+`<p class="modal-description">${esc(s.student_name)} · ${esc(s.assignment_title)} · 第 ${s.version} 次</p><div class="confirmation-summary"><strong>${decision==='verified'?'成绩：'+pendingReview.score+' 分':'退回原因'}</strong><p class="body-copy">${esc(f.feedback||'无额外反馈')}</p></div><div class="modal-actions">${btn('继续检查','close-modal','secondary')}${btn('确认处理','review-confirm')}</div>`);}
const actions={identity,design:showDesign,help:()=>openModal('help',modalHead('师生事务办理指南')+'<ol class="help-list"><li>教师创建课堂，保存作业草稿后单独发布。</li><li>学生使用课堂码加入，从学习中心进入实践记录。</li><li>查资料、写代码、申请运行，完成评测。</li><li>抄写编号、补齐材料并完成三轮确认。</li><li>教师核实通过评分，或填写原因退回。</li><li>学生查结果；退回后修改并重新提交。</li></ol>'),recover,'close-modal':closeModal,refresh:()=>refresh(),activate:e=>activate(e.dataset.key),
  lobby:()=>{closeModal();profile=null;data=null;local.active=null;persist();go('dashboard');render();},
  'join-current':()=>openModal('join',modalHead('以学生身份加入本课堂')+joinForm(profile.room.code)),
  invite:()=>copy(location.origin+location.pathname+'?class='+profile.room.code),'copy-token':()=>copy(profile.token),
  save:()=>{persist();toast('草稿已保存在当前浏览器，尚未提交。');},run:showRun,'copy-evaluation':()=>copy(draft().evaluation.id),'copy-solution':()=>copy(PRESETS[task().preset].solution),'export-code':()=>download('main.js',draft().code,'text/javascript'),
  extract:()=>{const d=draft();d.attachment={name:'main.js',content:d.code};if(!d.filename)d.filename='main.js';persist();render();toast('已提取当前代码，请查阅命名规则。');},
  archive:()=>{const errors=studentErrors(draft(),task(),data.room,profile.student);if(errors.length){failStudent(errors);return;}confirmation=0;showConfirmation();},
  'open-transactions':()=>{closeModal();go('transactions');},
  'confirm-next':async()=>{const valid=confirmation===1?$('#confirm-text').value==='确认归档':$('#confirm-check').checked;if(!valid){toast(confirmation===1?'请输入完整的“确认归档”。':'请先勾选确认。');return;}const d=draft();d.stats.confirmations++;persist();if(confirmation<2){confirmation++;showConfirmation();return;}const errors=studentErrors(d,task(),data.room,profile.student);if(errors.length){closeModal();failStudent(errors);return;}d.nonce??=crypto.randomUUID();persist();try{await mutate('/api/assignments/'+task().id+'/submit',{...d,history:undefined,logs:undefined,nonce:d.nonce});d.nonce=null;persist();toast('提交已保存到课堂，等待教师核实。');}catch(e){closeModal();failStudent([e.message]);}},
  'download-receipt':()=>{const s=latest(task().id);download(s.id+'.json',JSON.stringify({platform:'课还没交 · 双端演示',classroom:data.room,student:profile.student,submission:s},null,2));},
  'queue-filter':e=>{queueFilter=e.dataset.filter;render();},
  'publish-task':e=>openModal('publish',modalHead('发布作业给本课堂学生')+`<p class="modal-description">发布后，本课堂学生即可查看、运行代码并提交。</p><div class="modal-actions">${btn('暂不发布','close-modal','secondary')}${btn('确认发布','publish-confirm','primary',`data-id="${e.dataset.id}"`)}</div>`),
  'publish-confirm':async e=>{await mutate('/api/assignments/'+e.dataset.id+'/publish');toast('作业已发布，学生刷新后可见。');},
  'close-task':e=>openModal('close-task',modalHead('结束收取本次作业')+`<p class="modal-description">关闭后不能新增提交，仍可核实已有记录。截止前可以重新开放。</p><div class="modal-actions">${btn('保留开放','close-modal','secondary')}${btn('确认结束收取','close-task-confirm','primary',`data-id="${e.dataset.id}"`)}</div>`),
  'close-task-confirm':async e=>{await mutate('/api/assignments/'+e.dataset.id+'/close');toast('已结束收取。');},'reopen-task':async e=>{await mutate('/api/assignments/'+e.dataset.id+'/reopen');toast('作业已重新开放。');},
  'review-approve':()=>prepareReview('verified'),'review-return':()=>prepareReview('returned'),'review-confirm':async()=>{const s=data.submissions.find(s=>s.id===route().split('/')[2]);await mutate('/api/submissions/'+s.id+'/review',pendingReview);go('teacher/reviews');toast(pendingReview.decision==='verified'?'核实通过，学生可以查询成绩。':'已退回，学生可以修改后重新提交。');}
};
document.addEventListener('click',async e=>{if(e.target.closest('a,button,summary')&&draft())draft().stats.clicks++;const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(busy)return;try{await actions[el.dataset.action]?.(el);}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{const el=e.target,d=draft();if(el.id==='code-editor'&&d){d.code=el.value;persist();$('#line-numbers').textContent=d.code.split('\n').map((_,i)=>i+1).join('\n');$('#draft-status').textContent='草稿已保留 · 当前版本需要重新评测';$('#current-pass').innerHTML=d.evaluation?.passed&&d.evaluation.code===d.code?badge('当前版本通过','success'):'';}if(el.dataset.draft&&d){d[el.dataset.draft]=el.value;persist();}if(el.dataset.teacher)teacherForm[el.dataset.teacher]=el.value;if(el.dataset.review){const id=route().split('/')[2];if(reviews[id])reviews[id][el.dataset.review]=el.type==='checkbox'?el.checked:el.value;}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.teacher==='preset'){const p=PRESETS[el.value];teacherForm.preset=el.value;teacherForm.title='第 1 关：'+p.label;teacherForm.description=p.description;render();}if(el.id==='attachment-input'){const f=el.files?.[0];if(!f)return;if(f.size>32768){failStudent(['附件超过 32 KB。']);return;}const d=draft();d.attachment={name:f.name,content:await f.text()};d.filename=f.name;persist();render();}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['create-room','join-room','recover-session','create-assignment','run-form'].includes(f.id))return;e.preventDefault();if(busy||!f.reportValidity())return;if(f.id==='run-form'){await startRun(f);return;}const v=Object.fromEntries(new FormData(f));busy=true;f.querySelector('button[type="submit"]').disabled=true;try{if(f.id==='create-room'||f.id==='join-room'){const result=await api(f.id==='create-room'?'/api/classrooms':'/api/classrooms/join',{method:'POST',body:v,token:null});saveProfile(result);busy=false;closeModal();go('dashboard');render();toast(result.role==='teacher'?'课堂已创建，请在身份面板保留教师恢复口令。':'已加入课堂。');}if(f.id==='recover-session'){const token=v.token.trim(),result=await api('/api/session',{token});saveProfile({...result,token});busy=false;closeModal();go('dashboard');render();toast('身份已恢复。');}if(f.id==='create-assignment'){data=await api('/api/assignments',{method:'POST',body:{...v,dueAt:v.dueAt?new Date(v.dueAt).toISOString():null}});busy=false;go('teacher/tasks');render();toast('草稿已保存，还需要单独发布。');}}catch(error){busy=false;toast(error.message);f.querySelector('button[type="submit"]').disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&e.target.id==='code-editor'&&!e.target.readOnly){e.preventDefault();const el=e.target;el.setRangeText('  ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}});
window.addEventListener('hashchange',()=>{if(!busy)closeModal();render();window.scrollTo(0,0);});
setInterval(()=>{if(profile&&!document.hidden&&!busy)refresh(true);},12000);
render();if(profile)refresh();
